  "audio-size": { cmd: "bash -c 'set -o pipefail; mkdir -p target; ~/dev/abyme/scripts/gate-slot run bevy-ts:script-audio -- bench/audio-size/sizes.sh 2>&1 | tee target/audio-size.log'" },
